import (
	"errors"
	"io"
	"strings"

	"MODULE_NAME/internal/headers"
)

type parserState int

const (
	stateInitialized parserState = iota
	stateParsingHeaders
	stateDone
)

type Request struct {
	RequestLine RequestLine
	Headers     headers.Headers
	state       parserState
}

type RequestLine struct {
	HttpVersion   string
	RequestTarget string
	Method        string
}

func RequestFromReader(reader io.Reader) (*Request, error) {
	buf := make([]byte, 8)
	readToIndex := 0
	req := &Request{
		state:   stateInitialized,
		Headers: headers.NewHeaders(),
	}

	for req.state != stateDone {
		// 1. Expand buffer if it is full
		if readToIndex == len(buf) {
			// TODO: Double the buffer size and copy over the old bytes
			newBuf := make([]byte, len(buf)*2)
			copy(newBuf, buf)
			buf = newBuf
		}

		// 2. Read next chunk from reader into free space (from readToIndex onwards)
		n, err := reader.Read(buf[readToIndex:])
		if err == io.EOF {
			// TODO: If we hit EOF before stateDone, return an error; otherwise break
			if req.state != stateDone {
				return nil, errors.New("Unexpected EOF")
			}
			break
		}
		if err != nil {
			return nil, err
		}

		// 3. Update cursor with newly read bytes
		readToIndex += n

		// 4. Parse as much of the buffer as possible
		bytesParsed, err := req.parse(buf[:readToIndex])
		if err != nil {
			return nil, err
		}

		// 5. Shift unparsed bytes to index 0 and decrement readToIndex
		if bytesParsed > 0 {
			// TODO: Shift remaining bytes using copy() and adjust readToIndex
			copy(buf, buf[bytesParsed:readToIndex])
			readToIndex -= bytesParsed
		}
	}

	return req, nil
}

func parseRequestLine(str string) (RequestLine, int, error) {
	// TODO: Find "\r\n". If not found, return empty RequestLine, 0, nil
	// TODO: Split by space and validate (3 parts, Uppercase method, HTTP/1.1 version)
	// TODO: Return populated RequestLine, bytes consumed (index + 2), nil
	idx := strings.Index(str, "\r\n")
	if idx == -1 {
		return RequestLine{}, 0, nil
	}

	reqLine := str[:idx]
	parts := strings.Split(reqLine, " ")

	if len(parts) < 3 {
		return RequestLine{}, 0, errors.New("malformed request line")
	}

	if strings.ToUpper(parts[0]) != parts[0] {
		return RequestLine{}, 0, errors.New("method of RequestLine must be all Upper")
	}

	versionParts := strings.Split(parts[2], "/")
	if len(versionParts) < 2 || versionParts[1] != "1.1" {
		return RequestLine{}, 0, errors.New("version must be 1.1")
	}

	return RequestLine{
		Method:        parts[0],
		HttpVersion:   versionParts[1],
		RequestTarget: parts[1],
	}, idx + 2, nil
}

func (r *Request) parse(data []byte) (int, error) {
	totalBytesParsed := 0

	// Loop as long as we're not done and there are still bytes to try parsing
	for r.state != stateDone {
		// TODO: Call r.parseSingle on data[totalBytesParsed:]
		// TODO: If err != nil, return 0, err
		// TODO: If bytes parsed is 0 (needs more data), break out of loop
		// TODO: Add parsed bytes to totalBytesParsed

		n, err := r.parseSingle(data[totalBytesParsed:])
		if err != nil {
			return 0, err
		}

		if n == 0 {
			break
		}

		totalBytesParsed += n

	}

	return totalBytesParsed, nil
}

func (r *Request) parseSingle(data []byte) (int, error) {
	switch r.state {
	case stateInitialized:
		// TODO: Call parseRequestLine.
		// If parsed > 0, set r.RequestLine and change state to stateParsingHeaders.
		// Return bytes parsed.
		reqLine, n, err := parseRequestLine(string(data))
		if err != nil {
			return 0, err
		}
		if n > 0 {
			r.RequestLine = reqLine
			r.state = stateParsingHeaders
		}
		return n, nil
	case stateParsingHeaders:
		// TODO: Call r.Headers.Parse(data).
		// If done is true, change state to stateDone.
		// Return bytes parsed.
		n, done, err := r.Headers.Parse(data)
		if err != nil {
			return 0, err
		}
		if done {
			r.state = stateDone
		}
		return n, nil
	case stateDone:
		return 0, errors.New("error: trying to read data in a done state")

	default:
		return 0, errors.New("error: unknown state")
	}
}
