package headers

import (
	"errors"
	"regexp"
	"strings"
)

type Headers map[string]string

func NewHeaders() Headers {
	return make(Headers)
}

func (h Headers) Parse(data []byte) (n int, done bool, err error) {
	idx := strings.Index(string(data), "\r\n")

	if idx == -1 {
		return 0, false, nil
	}

	if idx == 0 {
		return 2, true, nil
	}

	line := data[:idx]

	key, value, ok := strings.Cut(string(line), ":")
	if !ok {
		return 0, false, errors.New("a header should be a key:value pair only")
	}

	if key == "" {
		return 0, false, errors.New("key can't be empty")
	}
	if strings.TrimSpace(key) != key {
		return 0, false, errors.New("no spaces are allowed between : and the key")
	}
	if !isValidStringRegex(key) {
		return 0, false, errors.New("key isn't valid")
	}
	key = strings.ToLower(key)
	value = strings.TrimSpace(value)

	if h[key] != "" {
		h[key] += ", " + value
	} else {
		h[key] = value
	}

	return idx + 2, false, nil
}

func isValidStringRegex(s string) bool {
	pattern := `^[a-zA-Z0-9!#\$%&'\*\+\-\.\^_\` + "`" + `\|~]+$`
	re := regexp.MustCompile(pattern)
	return re.MatchString(s)
}

